package com.leetcode.backend.model;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="assessment_creator_documents",indexes=@Index(name="idx_creator_document_application",columnList="application_id")) public class AssessmentCreatorDocument {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @OneToOne(fetch=FetchType.LAZY) @JoinColumn(name="application_id",nullable=false,unique=true) private AssessmentCreatorApplication application; @Column(name="storage_name",nullable=false,unique=true,length=100) private String storageName; @Column(name="original_name",nullable=false,length=255) private String originalName; @Column(name="content_type",nullable=false,length=80) private String contentType; @Column(nullable=false) private long size; @Column(name="created_at",nullable=false) private LocalDateTime createdAt; @Column(name="deleted_at") private LocalDateTime deletedAt; @PrePersist void create(){createdAt=LocalDateTime.now();}
 public Long getId(){return id;} public AssessmentCreatorApplication getApplication(){return application;} public void setApplication(AssessmentCreatorApplication v){application=v;} public String getStorageName(){return storageName;} public void setStorageName(String v){storageName=v;} public String getOriginalName(){return originalName;} public void setOriginalName(String v){originalName=v;} public String getContentType(){return contentType;} public void setContentType(String v){contentType=v;} public long getSize(){return size;} public void setSize(long v){size=v;} public LocalDateTime getCreatedAt(){return createdAt;} public LocalDateTime getDeletedAt(){return deletedAt;} public void setDeletedAt(LocalDateTime v){deletedAt=v;}
}
